namespace sv_60d2ab2f6e5c4fcfa949d8f3c14513d1.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts and notifies all subscribers
/// when fresh data arrives.  Each circuit gets its own instance, so concurrent
/// managers see independent counts.
/// </summary>
public sealed class InventoryAlertService
{
    private static readonly Random _rng = Random.Shared;

    /// <summary>Current cached alert count for the active warehouse.</summary>
    public int CurrentAlertCount { get; private set; }

    /// <summary>Raised after <see cref="RefreshAsync"/> fetches new data.</summary>
    public event Func<Task>? OnAlertCountChanged;

    /// <summary>Simulates a database query returning low-stock item count (0–15).</summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        int count = _rng.Next(0, 16);
        return Task.FromResult(count);
    }

    /// <summary>
    /// Fetches fresh data for the given warehouse and notifies every subscriber.
    /// Called by the polling component and on warehouse change.
    /// </summary>
    public async Task RefreshAsync(string warehouseId)
    {
        CurrentAlertCount = await GetLowStockCountAsync(warehouseId);

        if (OnAlertCountChanged is not null)
            await OnAlertCountChanged.Invoke();
    }
}

