@using sv_60d2ab2f6e5c4fcfa949d8f3c14513d1.Services
@implements IDisposable
@inject WarehouseStateService WarehouseState

<select class="form-select form-select-sm"
        style="width: auto; display: inline-block;"
        value="@WarehouseState.CurrentWarehouseId"
        @onchange="OnWarehouseChanged">
    @foreach (var (id, name) in WarehouseStateService.AvailableWarehouses)
    {
        <option value="@id">@name</option>
    }
</select>

@code {
    [Inject] private InventoryAlertService AlertService { get; set; } = default!;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += StateHasChangedAsync;
    }

    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var warehouseId = e.Value?.ToString() ?? WarehouseStateService.AvailableWarehouses[0].Id;
        await WarehouseState.SetWarehouseAsync(warehouseId);
        // Immediately refresh alerts for the newly selected warehouse
        await AlertService.RefreshAsync(warehouseId);
    }

    private Task StateHasChangedAsync()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        WarehouseState.OnChange -= StateHasChangedAsync;
    }
}

