@page "/dashboard"
@using sv_60d2ab2f6e5c4fcfa949d8f3c14513d1.Services
@rendermode InteractiveServer
@implements IDisposable
@inject WarehouseStateService WarehouseState
@inject InventoryAlertService AlertService

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>
<p>Currently viewing: <strong>@WarehouseState.CurrentWarehouseName</strong></p>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            Items below minimum level:
            @if (AlertService.CurrentAlertCount > 0)
            {
                <span class="badge bg-danger fs-5 ms-2">@AlertService.CurrentAlertCount</span>
            }
            else
            {
                <span class="badge bg-success fs-5 ms-2">0</span>
            }
        </p>
        <p class="text-muted"><small>Auto-refreshes every 10 seconds</small></p>
    </div>
</div>

@code {
    private CancellationTokenSource? _cts;

    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnWarehouseChanged;
        AlertService.OnAlertCountChanged += OnAlertDataChanged;
    }

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            // Initial fetch + start polling
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
            _cts = new CancellationTokenSource();
            _ = PollAsync(_cts.Token);
        }
    }

    private async Task PollAsync(CancellationToken ct)
    {
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
        while (await timer.WaitForNextTickAsync(ct))
        {
            await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        }
    }

    private async Task OnWarehouseChanged()
    {
        await AlertService.RefreshAsync(WarehouseState.CurrentWarehouseId);
        await InvokeAsync(StateHasChanged);
    }

    private Task OnAlertDataChanged()
    {
        InvokeAsync(StateHasChanged);
        return Task.CompletedTask;
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        WarehouseState.OnChange -= OnWarehouseChanged;
        AlertService.OnAlertCountChanged -= OnAlertDataChanged;
    }
}

